// flowgate.v02.0048 T#3 — one document as the v0.1 API gives it (NR0003 §2.1 / §2.2, D#1 §6.3).
// T#3 owns the single read; T#5 adds the content and relation reads to this file. Other feature
// sets call `documentRead` and do not edit this file.
//
//   read   GET /api/v1/documents/{doc_id}   (perm_document_read; 404 when there is no such document)
//
// flowgate.v02.0048 T#5 — the documents tab's reads, on the same endpoint (no new server API):
//   detail     the read above plus the review extras the tab shows: the rejection history
//              (`rejection_history`, oldest first as stored) and whether an AI review exists
//              (`ai_review` / `ai_review_history` — existence only, never a count: D#1 §10.4)
//   relations  the documents a document superseded (the Canvas `document.supersedes` ids), one
//              read each; a failed one is answered as missing instead of failing the others
// The body (`/content`) is not read by the Inspector: it keeps summaries and opens the document itself
// in the document window (D#1 §9, §10.2; flowgate.v02.0053 T#3).
//
// flowgate.v02.0053 T#3 — the document window's body read and save, on the v0.1 endpoints the v0.1
// main screen uses (MainPanel openEditModal / saveEditContent, MdViewer). No new server API.
//   content read   GET   /api/v1/documents/content?doc_id=<doc_id>    (perm_document_read)
//   content save   PATCH /api/v1/documents/content  { doc_id, content } (perm_document_update)
// The body is the stored file as it is, frontmatter included. A document whose file is not written yet
// (a report before its run) answers 404 on the read; that is read as an empty body, so the document
// opens as an empty document and a save writes its file (the server creates it). Every other failure is
// thrown as it is (see documentErrorOf): the save answers 422 when the document is not editable (final
// approval, status) and 409 while the Flow's AI runs, for a TR2 or a migrated conversation.
//
// The response is the documents row plus workflow / review extras; only the fields below are
// taken, snake_case -> camelCase. The v0.1 response shape is not changed.
//
// flowgate.v02.0068 T#1 — document upload / download (D §3.1, L §2.14 / §2.15). The upload / download
// buttons read the same document as `documentRead` and keep, besides the record (`is_editable` included),
// the server's `download_available` when it is a boolean (`toDocumentInfo` / `documentInfoRead`; the
// record shape other readers compare stays as it is). An upload is the content save above. The download
// is the existing canonical Markdown download (document-read permission):
//   download   GET /api/v1/document/{doc_id}/download   (403 / 404 no document or no file / 422 / 500)
// The file comes as a blob (the request carries the bearer header); a refusal also arrives as a blob and
// is read back into the JSON envelope before it is thrown, so documentErrorOf reads its status.
import { downloadBlobRequest, getRequest, patchRequest } from '@shared/api'
import { normalizeApiInput } from '@shared/apiErrors'
import { documentErrorOf } from '../documentError'

const API = '/api/v1'

export interface DocumentRecord {
  readonly docId: string
  readonly projectId: string | null
  /** v0.1 group id = Flow id. */
  readonly groupId: string | null
  readonly typeCode: string | null
  readonly seq: number | null
  readonly title: string
  /** Document status (draft / open / closed …), as sent. */
  readonly status: string | null
  /** Review status (pending_review / approved / rejected …), as sent. */
  readonly docReviewStatus: string | null
  readonly revisionNo: number | null
  readonly rejectionReason: string | null
  readonly supersededBy: string | null
  readonly updatedAt: string | null
  readonly isEditable?: boolean
  readonly groupDisposed?: boolean
}

type Raw = Record<string, unknown>

const text = (value: unknown): string | null => (typeof value === 'string' && value ? value : null)
const whole = (value: unknown): number | null => (typeof value === 'number' && Number.isInteger(value) ? value : null)

/** The v0.1 document response -> DocumentRecord. Throws when it carries no doc_id. */
export function toDocumentRecord(raw: unknown): DocumentRecord {
  const row: Raw = raw && typeof raw === 'object' ? (raw as Raw) : {}
  const docId = text(row.doc_id)
  if (docId === null) throw new Error('document response without doc_id')
  return {
    docId,
    projectId: text(row.project_id),
    groupId: text(row.group_id),
    typeCode: text(row.type_code),
    seq: whole(row.seq),
    title: typeof row.title === 'string' ? row.title : '',
    status: text(row.status),
    docReviewStatus: text(row.doc_review_status),
    revisionNo: whole(row.revision_no),
    rejectionReason: text(row.rejection_reason),
    supersededBy: text(row.superseded_by),
    updatedAt: text(row.updated_at),
    ...(typeof row.is_editable === 'boolean' ? { isEditable: row.is_editable } : {}),
    ...(typeof row.group_disposed === 'boolean' ? { groupDisposed: row.group_disposed } : {}),
  }
}

/** Reads one document. Transport errors are thrown as they are (see documentErrorOf). */
export async function documentRead(docId: string): Promise<DocumentRecord> {
  const response = await getRequest<unknown>(`${API}/documents/${encodeURIComponent(docId)}`)
  return toDocumentRecord(response.data)
}

/** A document as the upload / download buttons judge it (flowgate.v02.0068, L §2.15). */
export interface DocumentInfo extends DocumentRecord {
  /** The server has a readable Markdown file to download; absent when it did not say (as a boolean). */
  readonly downloadAvailable?: boolean
}

/** The v0.1 document response -> DocumentInfo: the record plus `download_available` when it is a boolean. */
export function toDocumentInfo(raw: unknown): DocumentInfo {
  const record = toDocumentRecord(raw)
  const value = (raw as Raw).download_available
  return typeof value === 'boolean' ? { ...record, downloadAvailable: value } : record
}

/** Reads one document for the upload / download buttons. Transport errors are thrown as they are. */
export async function documentInfoRead(docId: string): Promise<DocumentInfo> {
  const response = await getRequest<unknown>(`${API}/documents/${encodeURIComponent(docId)}`)
  return toDocumentInfo(response.data)
}

/** One rejection of a document (`rejection_history` item). */
export interface DocumentRejection {
  readonly rejectionId: string | null
  readonly reason: string
  readonly rejectedAt: string | null
  readonly rejectedBy: string | null
  /** How the AI answered this rejection when it re-submitted the document, if recorded. */
  readonly aiResponse: string | null
}

/** A document with what the documents tab shows besides its header fields. */
export interface DocumentDetail extends DocumentRecord {
  /** Rejections as stored: oldest first. */
  readonly rejectionHistory: readonly DocumentRejection[]
  /** An AI review exists for the document (existence only). */
  readonly hasAiReview: boolean
}

function toDocumentRejection(raw: unknown): DocumentRejection | null {
  if (!raw || typeof raw !== 'object') return null
  const item = raw as Raw
  const reason = text(item.reason)
  if (reason === null) return null
  return {
    rejectionId: text(item.rejection_id),
    reason,
    rejectedAt: text(item.rejected_at),
    rejectedBy: text(item.rejected_by),
    aiResponse: text(item.ai_response),
  }
}

/** The v0.1 document response -> DocumentDetail. Throws when it carries no doc_id. */
export function toDocumentDetail(raw: unknown): DocumentDetail {
  const record = toDocumentRecord(raw)
  const row = raw as Raw
  const history = Array.isArray(row.rejection_history) ? row.rejection_history : []
  const reviews = Array.isArray(row.ai_review_history) ? row.ai_review_history : []
  return {
    ...record,
    rejectionHistory: history.map(toDocumentRejection).filter((item): item is DocumentRejection => item !== null),
    hasAiReview: reviews.length > 0 || (!!row.ai_review && typeof row.ai_review === 'object'),
  }
}

/** Reads one document with its review extras. Transport errors are thrown as they are. */
export async function documentDetailRead(docId: string): Promise<DocumentDetail> {
  const response = await getRequest<unknown>(`${API}/documents/${encodeURIComponent(docId)}`)
  return toDocumentDetail(response.data)
}

/** A related document by id: its record, or null when it could not be read. */
export interface DocumentRelation {
  readonly docId: string
  readonly record: DocumentRecord | null
  /** What the read threw (see documentErrorOf), or null. */
  readonly error: unknown
}

/**
 * Reads related documents (e.g. the ids a document superseded) in the given order. Never throws:
 * each failed read is answered with `record: null` and its error, so one missing document does not
 * hide the others.
 */
export async function documentRelationsRead(docIds: readonly string[]): Promise<DocumentRelation[]> {
  const ids = [...new Set(docIds.filter((id) => typeof id === 'string' && id))]
  const settled = await Promise.allSettled(ids.map((id) => documentRead(id)))
  return settled.map((result, i) =>
    result.status === 'fulfilled'
      ? { docId: ids[i], record: result.value, error: null }
      : { docId: ids[i], record: null, error: result.reason },
  )
}

/** A document's stored body (flowgate.v02.0053 T#3). */
export interface DocumentContent {
  readonly docId: string
  /** The stored file as it is (frontmatter included); '' when the file is not written yet. */
  readonly content: string
  /** The file is not written yet (the read answered 404). */
  readonly missing: boolean
  readonly state?: 'readable' | 'unreadable'
  readonly reason?: 'file_path_missing' | 'file_not_found' | 'path_unresolved'
}

/** Reads a document's body. A missing file is an empty body; other errors are thrown as they are. */
export async function documentContentRead(docId: string): Promise<DocumentContent> {
  try {
    const response = await getRequest<unknown>(`${API}/documents/content?doc_id=${encodeURIComponent(docId)}`)
    const data = response.data as { content?: unknown } | null
    return { docId, content: typeof data?.content === 'string' ? data.content : '', missing: false }
  } catch (error) {
    if (documentErrorOf(error).kind === 'not_found') {
      const reason = normalizeApiInput(error).data.reason
      if (reason === 'file_path_missing' || reason === 'file_not_found' || reason === 'path_unresolved') {
        return { docId, content: '', missing: true, state: 'unreadable', reason }
      }
      return { docId, content: '', missing: true }
    }
    throw error
  }
}

/** Saves a document's whole body (frontmatter included). Errors are thrown as they are. */
export async function documentContentSave(docId: string, content: string): Promise<void> {
  await patchRequest<unknown>(`${API}/documents/content`, { doc_id: docId, content })
}

/** A downloaded document file (flowgate.v02.0068): the server's canonical Markdown and its file name. */
export interface DocumentDownload {
  readonly blob: Blob
  /** The `Content-Disposition` header as sent, or null (the caller picks the file name). */
  readonly disposition: string | null
}

/** Downloads a document's stored Markdown as the server keeps it. Errors are thrown as they are. */
export async function documentDownload(docId: string): Promise<DocumentDownload> {
  try {
    const response = await downloadBlobRequest(`${API}/document/${encodeURIComponent(docId)}/download`)
    const headers = (response.headers ?? {}) as Record<string, unknown>
    const disposition = headers['content-disposition']
    return { blob: response.data, disposition: typeof disposition === 'string' && disposition ? disposition : null }
  } catch (error) {
    await readDownloadRefusal(error)
    throw error
  }
}

async function readDownloadRefusal(error: unknown): Promise<void> {
  const response = error && typeof error === 'object' ? (error as Raw).response : null
  if (!response || typeof response !== 'object') return
  const holder = response as Raw
  const data = holder.data
  if (typeof Blob === 'undefined' || !(data instanceof Blob)) return
  try {
    holder.data = JSON.parse(await blobText(data))
  } catch {
    // Not JSON: the status alone is read.
  }
}

function blobText(blob: Blob): Promise<string> {
  if (typeof blob.text === 'function') return blob.text()
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(String(reader.result ?? ''))
    reader.onerror = () => reject(reader.error)
    reader.readAsText(blob)
  })
}
